  static List<Adhkar> getMorningAdhkar() {
    return morningAdhkar.map((adhkar) => Adhkar.fromJson({
      ...adhkar,
      'type': 'morning'
    })).toList();
  }

  static List<Adhkar> getEveningAdhkar() {
    return eveningAdhkar.map((adhkar) => Adhkar.fromJson({
